 * Copied as-is from shadcn@4.22.1 (dist/tailwind.css); keep in sync with upstream, don't edit.
 * Docs: https://ui.shadcn.com/docs/utils/scroll-fade, https://ui.shadcn.com/docs/utils/shimmer
 *
 * Installed into consumers at app/refer-utils.css by the registry (imported from globals.css):
 *   npx shadcn@latest add https://ds.tryrefer.com/r/refer/refer-utils.json --overwrite
 */

/* scroll-fade */
@property --scroll-fade-t {
  syntax: "<length-percentage>";
  inherits: false;
  initial-value: 0px;
